def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    bg = max(range(10), key=lambda c: sum(v == c for row in g for v in row))
    # Find the full-length non-background marker line.
    marker = None
    for r, row in enumerate(g):
        if row[0] != bg and all(v == row[0] for v in row):
            marker = ("h", r, row[0])
            break
    if marker is None:
        for c in range(w):
            vals = [g[r][c] for r in range(h)]
            if vals[0] != bg and all(v == vals[0] for v in vals):
                marker = ("v", c, vals[0])
                break
    if marker is None:
        return g
    orient, pos, marker_color = marker
    pts = [(r, c) for r in range(h) for c in range(w)
           if g[r][c] != bg and g[r][c] != marker_color]
    if not pts:
        return g
    # The object sits on one side of the marker. Extend a parallel line
    # just beyond the object's far edge, when the grid has room.
    if orient == "v":
        left = [p for p in pts if p[1] < pos]
        right = [p for p in pts if p[1] > pos]
        side_pts = left if left and (not right or len(left) >= len(right)) else right
        if not side_pts:
            return g
        if side_pts[0][1] < pos:
            target = min(c for r, c in side_pts) - 1
        else:
            target = max(c for r, c in side_pts) + 1
        if 0 <= target < w:
            for r in range(h):
                g[r][target] = 8
    else:
        above = [p for p in pts if p[0] < pos]
        below = [p for p in pts if p[0] > pos]
        side_pts = above if above and (not below or len(above) >= len(below)) else below
        if not side_pts:
            return g
        if side_pts[0][0] < pos:
            target = min(r for r, c in side_pts) - 1
        else:
            target = max(r for r, c in side_pts) + 1
        if 0 <= target < h:
            for c in range(w):
                g[target][c] = 8
    return g

